import{_ as o,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Resumo das opções selecionadas em campos múltiplos","description":"","frontmatter":{"title":"Resumo das opções selecionadas em campos múltiplos","id":"eploc-resumo-localizador-secundario","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.4.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eploc-resumo-localizador-secundario"}]]},"headers":[],"relativePath":"funcionalidades/eploc-resumo-localizador-secundario.md","filePath":"funcionalidades/eploc-resumo-localizador-secundario.md"}'),t={name:"funcionalidades/eploc-resumo-localizador-secundario.md"};function l(d,a,i,c,u,m){return e(),s("div",null,a[0]||(a[0]=[r('<h1 id="resumo-das-opcoes-selecionadas-em-campos-multiplos" tabindex="-1">Resumo das opções selecionadas em campos múltiplos <a class="header-anchor" href="#resumo-das-opcoes-selecionadas-em-campos-multiplos" aria-label="Permalink to &quot;Resumo das opções selecionadas em campos múltiplos&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Quando há mais de uma opção marcada num campo de seleção múltipla do eproc (como o de localizadores secundários ou o filtro &quot;Status&quot; da área de trabalho de minutas), o campo mostra só &quot;Selecionado X de Y&quot; (ou &quot;X de Y selecionados&quot;), sem dizer quais. Este recurso lista, logo abaixo do campo, as opções selecionadas, cada uma com um &quot;x&quot; para removê-la.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, abaixo de qualquer campo de seleção múltipla que mostre só a contagem das opções marcadas, como o de localizadores secundários e o filtro &quot;Status&quot; da área de trabalho de minutas.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Marque duas ou mais opções num campo de seleção múltipla (por exemplo, localizadores secundários).</li><li>Abaixo do campo aparecem pequenas etiquetas com o nome de cada um.</li><li>Clique no &quot;x&quot; de uma etiqueta para desmarcar aquela opção.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Quantidade de opções mostradas antes de recolher as demais num botão &quot;+N&quot;</td><td>5</td><td>Com mais opções marcadas que isso, só as primeiras aparecem; o botão &quot;+N&quot; mostra as demais numa área com rolagem, e &quot;Mostrar menos&quot; recolhe de novo.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nomes longos aparecem cortados com reticências; passe o mouse sobre a etiqueta para ver o nome completo.</li><li>Com uma única opção marcada, o resumo não aparece, porque o próprio campo já mostra o nome.</li><li>Se a caixa &quot;Incluir processo em outros localizadores&quot; for desmarcada, o resumo some, porque a seleção não será enviada.</li></ul>',11)]))}const q=o(t,[["render",l]]);export{p as __pageData,q as default};
